const express = require('express');
const Pool = require('pg-pool');
const { TenantAdminCheck } = require('../services/tenantCheck');

const app = express();

const tenantDbPools = {};

function resolveTenantPool(tenantId) {
  if (!tenantDbPools[tenantId]) {
    tenantDbPools[tenantId] = new Pool({
      host: 'tenant-db-cluster.internal',
      database: `db_tenant_${tenantId}`,
      user: 'export_worker',
      password: process.env.EXPORT_DB_PASS
    });
  }
  return tenantDbPools[tenantId];
}

app.get('/api/database/export-dump', async (req, res) => {
  if (!req.user || !req.user.tenantId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { tenantId, tableName } = req.query;

  if (!tenantId || !tableName) {
    return res.status(400).json({ error: 'tenantId and tableName query params required' });
  }

  // Enforce tenant boundary and administrator role
  if (req.user.tenantId !== tenantId) {
    return res.status(403).json({ error: 'Access denied: cannot export database of another tenant' });
  }

  const isAdmin = await TenantAdminCheck.isAdmin(req.user.id, tenantId);
  if (!isAdmin) {
    return res.status(403).json({ error: 'Access denied: tenant administrator privileges required' });
  }

  const pool = resolveTenantPool(tenantId);

  // Whitelist allowable export tables to prevent SQL injection
  const allowedTables = ['users', 'orders', 'products', 'audit_logs'];
  if (!allowedTables.includes(tableName)) {
    return res.status(400).json({ error: 'Invalid or restricted table name' });
  }

  try {
    const { rows } = await pool.query(`SELECT * FROM ${tableName} LIMIT 1000`);
    res.setHeader('Content-Type', 'application/json');
    res.send(JSON.stringify({ tenantId, table: tableName, data: rows }));
  } catch (err) {
    res.status(500).json({ error: 'Dump failed' });
  }
});

app.listen(9103);
